create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','tester');
create type public.review_status as enum ('draft','proposed','approved','rejected');
create table public.profiles(user_id uuid primary key references auth.users on delete cascade,role app_role not null default 'tester',display_name text not null,access_expires_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table public.companies(id uuid primary key default gen_random_uuid(),canonical_name text not null,domain text,legal_details text,name_variants text[] not null default '{}',created_at timestamptz not null default now());
create table public.logo_versions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies,storage_path text not null unique,preview_path text,original_filename text not null,mime_type text not null,byte_size bigint not null check(byte_size>0),sha256 text not null,source_url text,obtained_at date,replaces_id uuid references public.logo_versions,created_by uuid references auth.users,created_at timestamptz not null default now(),unique(sha256));
create table public.method_versions(id uuid primary key default gen_random_uuid(),version text not null unique,definitions jsonb not null,exclusions jsonb not null default '{}',processing_params jsonb not null default '{}',supersedes_id uuid references public.method_versions,created_by uuid references auth.users,created_at timestamptz not null default now());
create table public.annotations(id uuid primary key default gen_random_uuid(),logo_version_id uuid not null references public.logo_versions,method_version_id uuid not null references public.method_versions,author_id uuid not null references auth.users,values jsonb not null,comment text,status review_status not null default 'draft',reviewed_by uuid references auth.users,reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.corpora(id uuid primary key default gen_random_uuid(),name text not null,description text,locked_at timestamptz,created_by uuid references auth.users,created_at timestamptz not null default now());
create table public.corpus_items(corpus_id uuid references public.corpora on delete cascade,logo_version_id uuid references public.logo_versions,annotation_id uuid references public.annotations,company_group jsonb not null default '{}',position int not null,primary key(corpus_id,logo_version_id));
create table public.analysis_runs(id uuid primary key default gen_random_uuid(),corpus_id uuid not null references public.corpora,method_version_id uuid not null references public.method_versions,program_version text not null,parameters jsonb not null,seed bigint,frequency_tables jsonb not null,results jsonb not null,status text not null check(status in('queued','running','complete','failed')),created_by uuid references auth.users,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.tester_scopes(user_id uuid references auth.users on delete cascade,company_id uuid references public.companies on delete cascade,primary key(user_id,company_id));
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz not null default now());
create or replace function public.active_profile() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where user_id=auth.uid() and revoked_at is null and (access_expires_at is null or access_expires_at>now()))$$;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where user_id=auth.uid() and role='owner' and revoked_at is null and (access_expires_at is null or access_expires_at>now()))$$;
alter table profiles enable row level security;alter table companies enable row level security;alter table logo_versions enable row level security;alter table method_versions enable row level security;alter table annotations enable row level security;alter table corpora enable row level security;alter table corpus_items enable row level security;alter table analysis_runs enable row level security;alter table tester_scopes enable row level security;alter table audit_log enable row level security;
create policy owner_all_profiles on profiles for all using(is_owner()) with check(is_owner());create policy self_profile on profiles for select using(user_id=auth.uid() and active_profile());
create policy active_read_companies on companies for select using(active_profile() and (is_owner() or exists(select 1 from tester_scopes s where s.user_id=auth.uid() and s.company_id=companies.id)));create policy owner_write_companies on companies for all using(is_owner()) with check(is_owner());
create policy active_read_logos on logo_versions for select using(active_profile() and (is_owner() or exists(select 1 from tester_scopes s where s.user_id=auth.uid() and s.company_id=logo_versions.company_id)));create policy owner_write_logos on logo_versions for all using(is_owner()) with check(is_owner());create policy tester_insert_logos on logo_versions for insert with check(active_profile() and created_by=auth.uid());
create policy active_read_methods on method_versions for select using(active_profile());create policy owner_write_methods on method_versions for all using(is_owner()) with check(is_owner());
create policy scoped_annotations on annotations for select using(active_profile() and (is_owner() or author_id=auth.uid()));create policy tester_annotation_insert on annotations for insert with check(active_profile() and author_id=auth.uid() and status in('draft','proposed'));create policy tester_annotation_update on annotations for update using(active_profile() and author_id=auth.uid() and status in('draft','proposed')) with check(author_id=auth.uid() and status in('draft','proposed'));create policy owner_annotations on annotations for all using(is_owner()) with check(is_owner());
create policy active_read_corpora on corpora for select using(active_profile());create policy active_read_items on corpus_items for select using(active_profile());create policy active_read_runs on analysis_runs for select using(active_profile());create policy owner_corpora on corpora for all using(is_owner()) with check(is_owner());create policy owner_items on corpus_items for all using(is_owner()) with check(is_owner());create policy owner_runs on analysis_runs for all using(is_owner()) with check(is_owner());create policy owner_scopes on tester_scopes for all using(is_owner()) with check(is_owner());create policy owner_audit on audit_log for select using(is_owner());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('logos','logos',false,10485760,array['image/png','image/jpeg','image/webp','image/svg+xml','image/gif']) on conflict(id) do update set public=false;
create policy logo_owner_storage on storage.objects for all using(bucket_id='logos' and is_owner()) with check(bucket_id='logos' and is_owner());create policy logo_scoped_read on storage.objects for select using(bucket_id='logos' and active_profile());create policy tester_own_upload on storage.objects for insert with check(bucket_id='logos' and active_profile() and (storage.foldername(name))[1]='tester' and (storage.foldername(name))[2]=auth.uid()::text);
